it('rejects a wrong-typed field without leaking the offending value', async () => {
  const recordedLogs: any[] = [];
  setLogger({
    debug: () => {},
    info: () => {},
    warn: (cat, msg, data) => recordedLogs.push({cat, msg, data}),
    error: () => {},
  });

  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'secret_tool',
      description: 'd',
      inputSchema: {type: 'object', properties: {password: {type: 'string'}}},
    },
    async () => 'ok'
  );

  const secretValue = 'VERY_SECRET_123';
  const response = await registry.execute('secret_tool', {password: 12345, secret: secretValue});

  expect(response.result).toContain('password');
  expect(response.result).not.toContain('12345');
  expect(response.result).not.toContain(secretValue);

  expect(recordedLogs.some(l => JSON.stringify(l).includes(secretValue))).toBe(false);
});

